<?php $pageTitle='Events';require 'header.php';$events=$pdo->query("SELECT e.*,c.name AS club_name,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id) AS registered FROM events e JOIN clubs c ON c.id=e.club_id WHERE e.event_date>=NOW() ORDER BY e.event_date ASC")->fetchAll(); ?>
<section class="page-intro"><span class="eyebrow">MAKE IT HAPPEN</span><h1>Upcoming campus events</h1><p>Find your next workshop, gathering, or new experience.</p></section><div class="event-list"><?php if(!$events): ?><div class="empty">No upcoming events yet. Come back soon!</div><?php endif; ?><?php foreach($events as $ev): ?><article class="event-card"><div class="event-date"><b><?=date('d',strtotime($ev['event_date']))?></b><span><?=date('M',strtotime($ev['event_date']))?></span></div><div class="event-content"><span class="tag"><?=e($ev['club_name'])?></span><h3><?=e($ev['title'])?></h3><p><?=e($ev['description'])?></p><p>📍 <?=e($ev['venue'])?> · <?=date('g:i A',strtotime($ev['event_date']))?></p><small><?=max(0,(int)$ev['capacity']-(int)$ev['registered'])?> seats remaining</small><a class="text-link" href="event.php?id=<?=$ev['id']?>">View details →</a></div></article><?php endforeach; ?></div>
<?php require 'footer.php'; ?>
